/**
 * fyd/css-variables: DTCG -> :root[data-theme] CSS custom properties.
 *
 * Deterministic: fixed header (no timestamps), token order follows the
 * platform source order, one declaration per line. The renderer switches
 * themes by setting data-theme on <html>; no theme classes.
 */
const HEADER = `/**
 * DO NOT EDIT. Generated by fyd-product-lane/builder/tokens/build.cjs
 * from DTCG 2025.10 sources. Rerun the build to regenerate.
 */`;

function themeFontTokens(allTokens, theme) {
  return allTokens.filter((t) => {
    const p = t.path;
    return (
      p[0] === "font" &&
      (p[1] === "display" || p[1] === "body") &&
      p[2] !== undefined &&
      p[2] !== theme
    );
  });
}

export function registerCssVariablesFormat(StyleDictionary) {
  StyleDictionary.registerFormat({
    name: "fyd/css-variables",
    format: ({ dictionary, options }) => {
      const theme = options.theme ?? "unknown";
      const selector = options.selector ?? `:root[data-theme="${theme}"]`;
      const skip = new Set(themeFontTokens(dictionary.allTokens, theme));
      const lines = dictionary.allTokens
        .filter((t) => !skip.has(t))
        .map((t) => `  --${t.name}: ${t.$value ?? t.value};`);
      return `${HEADER}\n${selector} {\n${lines.join("\n")}\n}\n`;
    },
  });
}
